export const deadCodeSweep = async (vm: Vm): Promise<Proposal | undefined> => {
  const candidates = parseKnip(await vm.exec("npm", ["run", "knip"], { cwd: "/work/fcp/frontend" }));
  const verdicts = await Promise.all(candidates.map((c) =>            // many readers, in parallel
    vm.helper({ model: "claude-sonnet-5-5", effort: "medium", task: "prove-unused", candidate: c,
                checks: ["dynamic imports", "string references", "stories", "e2e page objects", "@r/libs exports"] })));
  const proven = candidates.filter((_, i) => verdicts[i].proven);    // anything unsure is dropped
  if (proven.length === 0) return undefined;
  return vm.session({ task: "remove-dead-code", items: proven.slice(0, 10),   // one writer, at most 10 items
                      done: ["npm run verify", "npm run check-types", "npm run build"] });
};

